import{_ as a,o as t,c as r,a6 as o}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"AI 大模型解构","description":"拆开 Qwen、Llama、DeepSeek、GLM、Kimi 等主流开源大模型的“发动机盖”。","frontmatter":{"title":"AI 大模型解构","description":"拆开 Qwen、Llama、DeepSeek、GLM、Kimi 等主流开源大模型的“发动机盖”。","source":"https://daiw.org/manual/llm-anatomy"},"headers":[],"relativePath":"manual/llm/llm-anatomy/index.md","filePath":"manual/llm/llm-anatomy/index.md"}'),n={name:"manual/llm/llm-anatomy/index.md"};function l(s,e,i,g,m,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="ai-大模型解构" tabindex="-1">AI 大模型解构 <a class="header-anchor" href="#ai-大模型解构" aria-label="Permalink to &quot;AI 大模型解构&quot;">​</a></h1><blockquote><p>内容来源：<a href="https://daiw.org/manual/llm-anatomy" target="_blank" rel="noreferrer">daiw.org</a> · 作者 David（道雾轩） · 原文更新于 2026-11-06</p></blockquote><blockquote><p>拆开 Qwen、Llama、DeepSeek、GLM、Kimi 等主流开源大模型的“发动机盖”。</p></blockquote><h2 id="序-·-同一副骨架-各自的执念" tabindex="-1">序 · 同一副骨架，各自的执念 <a class="header-anchor" href="#序-·-同一副骨架-各自的执念" aria-label="Permalink to &quot;序 · 同一副骨架，各自的执念&quot;">​</a></h2><p>读完 <a href="https://daiw.org/manual/nanogpt" target="_blank" rel="noreferrer">nanoGPT 源码解读</a>，你已经握着一件趁手的工具：<strong>一个 GPT 的完整骨架</strong>——词嵌入、一摞 Transformer Block（注意力 + 前馈）、输出层。现在把镜头拉到 2024–2026 年那些真正的开源大模型：Qwen、Llama、DeepSeek、GLM、Kimi……</p><p><strong>惊人之处不是它们多不一样，而是它们多一样。</strong></p><p>把 DeepSeek-V3、Llama 4、Qwen3、GLM-4.5 的架构图并排摆开，你会发现：decoder-only 的堆叠、RoPE 位置编码、RMSNorm、SwiGLU 风格的前馈、Pre-Norm 残差——<strong>大同小异</strong>，和你在 nanoGPT 里读到的几乎是同一套。真正把它们区分开的，是<strong>少数几个位置上的不同下注</strong>。而恰恰是这几处“执念”，决定了一个模型是省显存的、是便宜的、是能塞进你显卡的，还是只能跑在集群上的。</p><p>所以这个专栏做的事很明确：</p><blockquote><p><strong>做一次“受控对比”：把共同的骨架摁住不动，只把各家分道扬镳的那几个“零件”拎出来，一维一维地并排看——这一处，Llama 怎么选、DeepSeek 怎么选、Qwen 怎么选，以及为什么。</strong></p></blockquote><h2 id="方法-一维一章-把差异逼出来" tabindex="-1">方法：一维一章，把差异逼出来 <a class="header-anchor" href="#方法-一维一章-把差异逼出来" aria-label="Permalink to &quot;方法：一维一章，把差异逼出来&quot;">​</a></h2><p>讲架构最容易犯的错，是“一个模型一章”——讲完 Llama 讲 Qwen，讲完 Qwen 讲 DeepSeek。这样讲，差异是<strong>散</strong>的，你读完只记得一堆名字，记不住谁和谁到底差在哪。</p><p>本专栏反过来：<strong>按“架构维度”切章</strong>。每一章锁定一个可对比的轴——比如“注意力怎么省 KV 缓存”“前馈用稠密还是 MoE”“归一化放前面还是后面”——然后把所有模型在这个轴上的选择<strong>拉成一排</strong>，讲清楚每种选择解决什么问题、代价是什么、谁选了它。差异是被<strong>逼出来</strong>的，不是被罗列的。</p><h2 id="两条主线-串起大半个故事" tabindex="-1">两条主线，串起大半个故事 <a class="header-anchor" href="#两条主线-串起大半个故事" aria-label="Permalink to &quot;两条主线，串起大半个故事&quot;">​</a></h2><p>2024–2026 年的大模型创新，乍看五花八门，其实<strong>大半在押注两件事</strong>：</p><ol><li><strong>省 KV 缓存</strong> —— 推理时，注意力的键值缓存（KV cache）是显存杀手。于是有了 MHA → MQA → GQA → <strong>MLA</strong>（DeepSeek 的杀手锏）这一路演进，以及 Gemma、GPT-OSS 的<strong>滑动窗口</strong>；到了 2026 年，又进一步演化出 <strong>3:1 线性注意力混合栈</strong>（Kimi K3 / K3.1 Pro 的 KDA + Gated MLA / Gated DSA、Qwen3.8-Max 的 Gated DeltaNet + Gated Attention）和<strong>跨层共享 FP4 KV 缓存</strong>（DeepSeek V4.1-Flash 的 CSA2）。这条线，回答的是“怎么让模型推理时更省、更便宜”。</li><li><strong>稀疏化（MoE）</strong> —— 把一个巨大的前馈层拆成几百个“专家”，每个 token 只激活其中几个。于是 671B 的 DeepSeek-V3 每步只算 37B，而 2026 年的万亿级旗舰（2.4T 的 Qwen3.8-Max、2.8T 的 Kimi K3 / K3.1 Pro）更是把总参数推到两万亿以上，每步仍只激活约 95B–104B。这条线，回答的是“怎么把参数堆到天上，又不让计算跟着爆炸”。</li></ol><p>抓住这两条主线，你就抓住了这一代大模型的<strong>主旋律</strong>。其余的（归一化的位置、长上下文外推、训练目标的花样）是重要的配角。</p><h2 id="路线图-共-13-篇" tabindex="-1">路线图（共 13 篇） <a class="header-anchor" href="#路线图-共-13-篇" aria-label="Permalink to &quot;路线图（共 13 篇）&quot;">​</a></h2><p><strong>开篇</strong></p><ul><li><strong>共同骨架：先看它们有多像</strong> —— 把“不变的部分”一次讲清，后面才好聚焦“变的部分”；并给出六个差异维度的总览地图。</li></ul><p><strong>主线一 · 省 KV 缓存</strong></p><ul><li><strong>注意力：从 MHA 到 MQA、GQA、MLA</strong> —— KV 缓存为什么是瓶颈，以及这一路“共享 / 压缩”的演进；DeepSeek 为什么偏偏选了最复杂的 MLA，以及 2026 年跨层 KV 共享与稀疏注意力的新进展。</li><li><strong>滑动窗口：Gemma 与 GPT-OSS 的局部注意力</strong> —— 用“只看附近”再省一刀，Mistral 为什么又把它去掉了，以及 2026 年滑动窗口有界重算与 3:1 线性注意力混合栈的接棒。</li></ul><p><strong>主线二 · 稀疏化（MoE）</strong></p><ul><li><strong>稠密 vs 稀疏：MoE 为什么突然统治了大模型</strong></li><li><strong>MoE 的三个旋钮：专家数、激活数、共享专家</strong> —— DeepSeek 的“多而小 + 共享” vs Llama 4 的“少而大” vs Qwen3“砍掉共享专家”（以及 Qwen3.8-Max 为什么又把共享专家请了回来）。</li><li><strong>让 MoE 训得稳、又均衡</strong> —— 辅助损失 vs DeepSeek 的“无辅助损失均衡”，以及为什么头几层要保持稠密。</li></ul><p><strong>其余关键维度</strong></p><ul><li><strong>归一化：RMSNorm、Pre / Post / 三明治、QK-Norm</strong> —— 一个“放哪儿”的小选择，如何左右训练稳定性。</li><li><strong>位置编码与长上下文：RoPE、YaRN，与 NoPE 的挑衅</strong></li><li><strong>训练侧的花样：MTP 多 token 预测、FP8、Muon</strong></li><li><strong>宽还是深，以及那些小执念</strong> —— 宽深之争、注意力里的 bias、attention sink、词表大小。</li></ul><p><strong>收尾</strong></p><ul><li><strong>四张脸谱：DeepSeek / Llama / Qwen / GLM 各自的组合拳</strong>（附 2026 三大旗舰架构进阶对照）</li><li><strong>一张大表 + 趋势</strong> —— 把所有维度收进一张对比表，并收束两条主线。</li></ul><h2 id="说明-以-架构-为准-并与站内-2026-旗舰专栏联动" tabindex="-1">说明：以“架构”为准，并与站内 2026 旗舰专栏联动 <a class="header-anchor" href="#说明-以-架构-为准-并与站内-2026-旗舰专栏联动" aria-label="Permalink to &quot;说明：以“架构”为准，并与站内 2026 旗舰专栏联动&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>开源模型迭代极快。本专栏聚焦<strong>架构层面的本质选择</strong>，以 2024–2025 年奠定格局的代表性版本为基准锚点（DeepSeek-V3、Llama 3/4、Qwen 2.5/3、GLM-4.5），并在各章末尾衔接 <strong>2026 年三大旗舰的架构演进</strong>。如果你想深入拆解 2026 年最新一代旗舰的完整技术细节，可以配合站内的三个专题专栏一起读：</p><ul><li><a href="https://daiw.org/manual/deepseek-v4-flash" target="_blank" rel="noreferrer">《DeepSeek V4.1 Flash 深度解析》</a>（不对称 CED 20+20 架构、CSA2 跨层共享 FP4 KV 缓存、Engram 静态记忆、Single-Pass mHC 残差、DSpark 投机解码）</li><li><a href="https://daiw.org/manual/qwen3-8-max" target="_blank" rel="noreferrer">《Qwen3.8-Max 深度解析》</a>（2.4T-A95B、3:1 Gated DeltaNet + Gated Attention 混合栈、512 路由专家 + 1 共享专家）</li><li><a href="https://daiw.org/manual/kimi-k3" target="_blank" rel="noreferrer">《Kimi K3 深度解析》</a>（2.8T-A104B、3:1 KDA + Gated MLA / Gated DSA 混合栈、LatentMoE 潜空间专家、AttnRes 注意力残差、原生 MXFP4 + Muon）</li></ul></div><h2 id="读之前-你最好有" tabindex="-1">读之前，你最好有 <a class="header-anchor" href="#读之前-你最好有" aria-label="Permalink to &quot;读之前，你最好有&quot;">​</a></h2><ul><li><strong>读过 <a href="https://daiw.org/manual/nanogpt" target="_blank" rel="noreferrer">nanoGPT 源码解读</a></strong>（至少读到注意力那章）—— 我们默认你已经知道“一个标准 Transformer Block 长什么样”，本专栏只讲<strong>它们在这之上改了什么</strong>。</li><li>不需要读过任何一篇原论文；关键结论我们会讲清来龙去脉。</li></ul><p>准备好了，先把“它们有多像”这件事看透——这样接下来每一处“不一样”才够扎眼：<a href="/Front2Full/manual/llm/llm-anatomy/common-skeleton">共同骨架：先看它们有多像</a>。</p>',32)])])}const h=a(n,[["render",l]]);export{u as __pageData,h as default};
